  double get progress {
    if (targetAmount == null || targetAmount == 0) return 0.0;
    return ((currentAmount ?? 0.0) / targetAmount!).clamp(0.0, 1.0);
  }

  bool get isAchieved => progress >= 1.0;

  String get formattedTarget => '\$${targetAmount?.toStringAsFixed(2) ?? '0.00'}';
  String get formattedCurrent => '\$${currentAmount?.toStringAsFixed(2) ?? '0.00'}';
  String get remainingAmount => '\$${((targetAmount ?? 0.0) - (currentAmount ?? 0.0)).toStringAsFixed(2)}';

  bool get isOverdue {
    if (deadline == null) return false;
    return deadline!.isBefore(DateTime.now()) && !isAchieved;
  }

  bool get isOnTrack {
    if (deadline == null || targetAmount == null || targetAmount == 0) return false;
    final daysLeft = deadline!.difference(DateTime.now()).inDays;
    if (daysLeft <= 0) return false;
    final totalDays = deadline!.difference(createdAt ?? DateTime.now()).inDays;
    if (totalDays <= 0) return false;
    final expectedProgress = 1 - (daysLeft / totalDays);
    return progress >= expectedProgress;
  }

