      currentAmount: (currentAmount ?? 0.0) + amount,
      contributions: newContributions,
      updatedAt: DateTime.now(),
      isCompleted: (currentAmount ?? 0.0) + amount >= (targetAmount ?? 0.0),
      completedAt: (currentAmount ?? 0.0) + amount >= (targetAmount ?? 0.0) 
